import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { AngularEditorConfig } from '@kolkov/angular-editor';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { AdminEmailModel } from 'src/app/data/model/person/AdminModel';
import { AdminService } from 'src/app/data/service/admin/admin.service';

@Component({
  selector: 'app-email',
  templateUrl: './email.component.html',
  styleUrls: ['./email.component.scss']
})
export class EmailComponent implements OnInit {

  form: FormGroup;

  editorConfig: AngularEditorConfig = {
    editable: true,
    spellcheck: true,
    height: '25rem',
    minHeight: '5rem',
    placeholder: 'متن...',
    translate: 'no',
    sanitize: true
  };

  constructor(
    private adminService: AdminService,
    private fb: FormBuilder,
    public toastController: ToastController,
    public loadingController: LoadingController,
    public alertController: AlertController,
    private router: Router) { }

  ngOnInit(): void {

    this.form = this.fb.group({
      title: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(1000)]],
      description: ['', [Validators.required, Validators.minLength(4), Validators.maxLength(1000000)]],
      isVerified: [true, [Validators.required]]
    });
  }

  async presentAlertConfirmOnSend() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟!؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'ارسال',
          handler: () => {
            this.onSend();
          }
        }
      ]
    });

    await alert.present();
  }

  onSend() {

    if (this.form.valid) {

      SharedIonic.loading(this.loadingController);

      this.adminService.AdminSendEmailToUsers(
        new AdminEmailModel(
          this.form.value.title,
          this.form.value.description,
          this.form.value.isVerified,
          0
        )
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {

            this.form.setValue({
              title: '',
              description: '',
              isVerified: true
            });
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }
}
